    </div>

    <!-- BOOKING MODAL -->
    <div id="booking-modal"
        style="display:none; position:fixed; inset:0; z-index:100000; background:rgba(58,46,34,0.55); align-items:center; justify-content:center;">
        <div class="modal-box">
            <button class="modal-close" onclick="closeBookingModal()">&times;</button>
            <div class="modal-title">Rezerwacja spotkania</div>
            <div class="modal-date" id="modal-date-label"></div>
            <div class="modal-fields">
                <div class="fg"><label for="bk-name">Imię i nazwisko</label><input type="text" id="bk-name"
                        placeholder="Jan Kowalski">
                    <div class="field-error" id="bk-name-err"></div>
                </div>
                <div class="fg"><label for="bk-tel">Telefon</label><input type="tel" id="bk-tel"
                        placeholder="+48 500 000 000">
                    <div class="field-error" id="bk-tel-err"></div>
                </div>
                <div class="fg"><label for="bk-email">E-mail</label><input type="email" id="bk-email"
                        placeholder="jan@example.com">
                    <div class="field-error" id="bk-email-err"></div>
                </div>
                <div class="fg">
                    <label for="bk-topic">Temat spotkania</label>
                    <select id="bk-topic">
                        <option value="">— Wybierz —</option>
                        <option>Kredyt hipoteczny</option>
                        <option>Kredyt firmowy</option>
                        <option>Refinansowanie</option>
                        <option>Analiza zdolności</option>
                        <option>Kredyt gotówkowy</option>
                        <option>Dom modułowy</option>
                        <option>Inne</option>
                    </select>
                </div>
                <div class="fg"><label for="bk-note">Dodatkowe informacje</label><textarea id="bk-note"
                        placeholder="Opcjonalnie — opisz krótko swoją sytuację…"></textarea></div>
            </div>
            <button class="btn btn-modal-submit" id="bk-submit" onclick="submitBooking()">Potwierdź rezerwację</button>
            <div class="form-err-general" id="bk-err-general">Wystąpił błąd serwera. Spróbuj ponownie lub zadzwoń
                bezpośrednio.</div>
            <div class="modal-ok" id="modal-ok" style="display:none">
                <div class="modal-ok-icon">&#10003;</div>
                <div class="modal-ok-text">Rezerwacja przyjęta!<br><span id="modal-ok-detail"></span></div>
            </div>
        </div>
    </div>
</body>

</html>